//! Flux home-page backgrounds: original scenes generated by `tools/backgrounds/gen.py`, each in a
//! pixel-art and a smooth style, with animated layers (twinkling stars, drifting clouds, a skater or
//! car crossing the scene) drawn on top.

use std::{path::Path, time::Duration};

use gpui::{prelude::*, *};

use crate::interface_config::{BackgroundStyle, InterfaceConfig};

pub struct Mover {
    /// Where the sprite's bottom edge sits, as a fraction of the 1920x1080 scene height.
    pub ground: f32,
    pub seconds: u64,
    /// Sprite size in 1080p pixels.
    pub size: (f32, f32),
    pub bob: bool,
}

pub struct Clouds {
    pub rows: &'static [(f32, u64)], // (top as fraction of scene height, seconds to cross)
    pub size: (f32, f32),
}

pub struct Scene {
    pub id: &'static str,
    pub name: &'static str,
    pub tagline: &'static str,
    pub stars: bool,
    pub clouds: Option<Clouds>,
    pub mover: Option<Mover>,
    pub shooting_stars: bool,
}

pub const SCENES: &[Scene] = &[
    Scene {
        id: "skatepark", name: "Skatepark", tagline: "Dusk session at the plaza",
        stars: true, shooting_stars: true, clouds: None,
        mover: Some(Mover { ground: 168. / 216., seconds: 14, size: (70., 80.), bob: true }),
    },
    Scene {
        id: "blocky-valley", name: "Blocky Valley", tagline: "Square sun, square clouds",
        stars: false, shooting_stars: false,
        clouds: Some(Clouds { rows: &[(0.08, 90), (0.2, 130), (0.04, 170)], size: (200., 50.) }),
        mover: None,
    },
    Scene {
        id: "cartoon-town", name: "Cartoon Town", tagline: "A sunny day on Evergreen-ish Terrace",
        stars: false, shooting_stars: false,
        clouds: Some(Clouds { rows: &[(0.06, 110), (0.16, 150)], size: (230., 120.) }),
        mover: Some(Mover { ground: 187. / 216., seconds: 11, size: (130., 50.), bob: false }),
    },
    Scene {
        id: "neon-city", name: "Neon City", tagline: "Synthwave skyline",
        stars: true, shooting_stars: true, clouds: None, mover: None,
    },
    Scene {
        id: "galaxy", name: "Galaxy", tagline: "A blocky planet adrift",
        stars: true, shooting_stars: true, clouds: None, mover: None,
    },
    Scene {
        id: "nether", name: "Nether", tagline: "Lava sea glow",
        stars: false, shooting_stars: false, clouds: None, mover: None,
    },
];

pub fn scene(id: &str) -> &'static Scene {
    SCENES.iter().find(|s| s.id == id).unwrap_or(&SCENES[0])
}

fn style_dir(style: BackgroundStyle) -> &'static str {
    match style {
        BackgroundStyle::Pixel => "pixel",
        BackgroundStyle::Smooth => "smooth",
    }
}

pub fn thumbnail_path(id: &str, style: BackgroundStyle) -> SharedString {
    format!("images/backgrounds/{id}/{}/thumb.png", style_dir(style)).into()
}

fn embedded(path: String) -> ImageSource {
    ImageSource::Resource(Resource::Embedded(path.into()))
}

/// Fills its parent (which must be `relative()`) with the configured background. `size` is the
/// parent's size, used to place sprites exactly where an object-fit:cover scene puts its ground.
pub fn render_background(size: Size<Pixels>, cx: &App) -> AnyElement {
    let config = InterfaceConfig::get(cx);
    let animate = config.animations;

    if config.background == "custom"
        && let Some(path) = config.custom_background.clone()
    {
        return div()
            .absolute()
            .inset_0()
            .child(img(ImageSource::Resource(Resource::Path(Path::new(&*path).into()))).size_full().object_fit(ObjectFit::Cover))
            .into_any_element();
    }

    render_scene(size, &config.background.clone(), cx)
}

/// One of the built-in scenes (in the configured art style), regardless of the Home background choice.
pub fn render_scene(size: Size<Pixels>, scene_id: &str, cx: &App) -> AnyElement {
    let config = InterfaceConfig::get(cx);
    let animate = config.animations;
    let scene = scene(scene_id);
    let dir = format!("images/backgrounds/{}/{}", scene.id, style_dir(config.background_style));

    // object-fit: cover math for a 1920x1080 scene.
    let (w, h) = (size.width.as_f32().max(1.), size.height.as_f32().max(1.));
    let scale = (w / 1920.).max(h / 1080.);
    let offset_y = (h - 1080. * scale) / 2.;
    let scene_y = move |frac: f32| offset_y + frac * 1080. * scale;

    let mut root = div()
        .absolute()
        .inset_0()
        .overflow_hidden()
        .child(img(embedded(format!("{dir}/background.png"))).absolute().inset_0().size_full().object_fit(ObjectFit::Cover));

    if !animate {
        return root.into_any_element();
    }

    if scene.stars {
        // Deterministic star field so stars don't jump between frames.
        let mut seed = 0x9e3779b9u32 ^ scene.id.len() as u32;
        let mut next = move || {
            seed ^= seed << 13;
            seed ^= seed >> 17;
            seed ^= seed << 5;
            (seed % 10_000) as f32 / 10_000.
        };
        for i in 0..28 {
            let (x, y, period, phase) = (next(), next() * 0.38, 1400 + (next() * 2600.) as u64, next());
            let star_size = px((2. + (i % 3) as f32) * scale.max(0.6));
            root = root.child(
                div()
                    .absolute()
                    .left(px(x * w))
                    .top(px(scene_y(y)))
                    .size(star_size)
                    .bg(gpui::white())
                    .with_animation(
                        ElementId::NamedInteger("flux-star".into(), i),
                        Animation::new(Duration::from_millis(period)).repeat(),
                        move |this, delta| {
                            let t = (delta + phase).fract();
                            let twinkle = 0.5 - 0.5 * (t * std::f32::consts::TAU).cos();
                            this.opacity(0.1 + 0.9 * twinkle)
                        },
                    ),
            );
        }
    }

    if scene.shooting_stars {
        let len = 140. * scale;
        root = root.child(
            div()
                .absolute()
                .h(px(2.))
                .w(px(len))
                .bg(linear_gradient(90., linear_color_stop(gpui::white().opacity(0.), 0.), linear_color_stop(gpui::white(), 1.)))
                .with_animation(
                    "flux-shooting-star",
                    Animation::new(Duration::from_secs(9)).repeat(),
                    move |this, delta| {
                        // Visible for the first 12% of each cycle, streaking down-right.
                        let t = (delta / 0.12).min(1.);
                        let x = w * 0.35 + t * w * 0.3;
                        let y = scene_y(0.05) + t * h * 0.18;
                        this.left(px(x)).top(px(y)).opacity(if delta < 0.12 { 1. - t } else { 0. })
                    },
                ),
        );
    }

    if let Some(clouds) = &scene.clouds {
        let (cw, ch) = (clouds.size.0 * scale, clouds.size.1 * scale);
        for (i, (top, seconds)) in clouds.rows.iter().copied().enumerate() {
            let start = i as f32 * 0.37;
            root = root.child(
                img(embedded(format!("{dir}/cloud.png")))
                    .absolute()
                    .w(px(cw))
                    .h(px(ch))
                    .top(px(scene_y(top)))
                    .with_animation(
                        ElementId::NamedInteger("flux-cloud".into(), i as u64),
                        Animation::new(Duration::from_secs(seconds)).repeat(),
                        move |this, delta| {
                            let t = (delta + start).fract();
                            this.left(px(-cw + t * (w + cw)))
                        },
                    ),
            );
        }
    }

    if let Some(mover) = &scene.mover {
        let (mw, mh) = (mover.size.0 * scale, mover.size.1 * scale);
        let ground = scene_y(mover.ground);
        let bob = mover.bob;
        root = root.child(
            img(embedded(format!("{dir}/mover.png")))
                .absolute()
                .w(px(mw))
                .h(px(mh))
                .with_animation(
                    "flux-mover",
                    Animation::new(Duration::from_secs(mover.seconds)).repeat(),
                    move |this, delta| {
                        let x = -mw + delta * (w + mw * 2.);
                        // The skater ollies over the funbox in the middle of the run.
                        let hop = if bob {
                            let t = ((delta - 0.42) / 0.12).clamp(0., 1.);
                            (t * std::f32::consts::PI).sin() * 40. * scale
                        } else {
                            (delta * 90.).sin().abs() * 1.5 * scale
                        };
                        this.left(px(x)).top(px(ground - mh - hop))
                    },
                ),
        );
    }

    root.into_any_element()
}
